CREATE TABLE users(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`cognito_user_id` varchar(255)  UNIQUE NULL COMMENT 'Amazon Cognito User Pool ID',`firebase_id` varchar(255)  UNIQUE NULL COMMENT 'Firebase User ID',`name` varchar(255)  NOT NULL,`email` varchar(255)  UNIQUE NULL,`phone` varchar(255)  UNIQUE NULL,`google_id` varchar(255)  NULL COMMENT 'Google OAuth ID for social login',`facebook_id` varchar(255)  NULL COMMENT 'Facebook OAuth ID for social login',`password` varchar(255)  NULL COMMENT 'Hashed password for traditional login',`user_type` varchar(255)  DEFAULT 'farmer' COMMENT 'farmer, buyer, admin',`preferred_language` varchar(255)  DEFAULT 'en' COMMENT 'en, hi, ta, te, mr, bn',`mfa_enabled` TINYINT(1)  DEFAULT 0,`latitude` DECIMAL(10,8)  NULL COMMENT 'Personal address GPS latitude (optional)',`longitude` DECIMAL(11,8)  NULL COMMENT 'Personal address GPS longitude (optional)',`pincode` varchar(10)  NULL COMMENT 'Postal code for address',`state` varchar(100)  NULL COMMENT 'State name',`district` varchar(100)  NULL COMMENT 'District name',`village` varchar(100)  NULL COMMENT 'Village/VPO name',`address_line` varchar(255)  NULL COMMENT 'Full address (house/building, street, landmark)')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;